/**
 * Tests for `checkConcurrentProposal` (Wave 11 / Builder 11).
 *
 * The helper queries the `bot_modal_proposals` table for OTHER pending
 * proposals in the same channel, same toolName, within the last 60 seconds,
 * and runs `fuzzyMatchCandidates` against the title extracted from each
 * candidate's `args` JSON.
 *
 * The DB layer is stubbed via the same drizzle-eq-sentinel pattern used in
 * the interactivity route tests so this spec is hermetic.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";

type FakeProposalRow = {
  id: string;
  toolName: string;
  channelId: string;
  userSlackId: string;
  status: "pending" | "submitted" | "cancelled" | "expired" | "failed";
  args: string;
  createdAt: Date;
};

function makeRow(overrides: Partial<FakeProposalRow> = {}): FakeProposalRow {
  return {
    id: `prop_${Math.random().toString(36).slice(2, 10)}`,
    toolName: "create_week_item",
    channelId: "C_TEST_001",
    userSlackId: "U_OTHER",
    status: "pending",
    args: JSON.stringify({ title: "Default Task" }),
    createdAt: new Date(),
    ...overrides,
  };
}

/**
 * Build a fake `getRunwayDb()` whose select chain returns the supplied rows
 * regardless of filters — the helper itself does the filtering in JS so we
 * don't need to model SQL semantics. This keeps the test honest about the
 * helper's actual behavior (it's the helper that decides which rows match,
 * not the stub).
 */
function setupConcurrencyMocks(rows: FakeProposalRow[]) {
  vi.resetModules();
  vi.doMock("drizzle-orm", async () => {
    const actual = await vi.importActual<Record<string, unknown>>("drizzle-orm");
    return {
      ...actual,
      eq: () => ({ _kind: "eq" }),
      and: (...args: unknown[]) => ({ _kind: "and", args }),
      gt: () => ({ _kind: "gt" }),
      ne: () => ({ _kind: "ne" }),
    };
  });
  vi.doMock("@/lib/db/runway", () => ({
    getRunwayDb: () => ({
      select: () => ({
        from: () => ({
          where: () => Promise.resolve(rows),
        }),
      }),
    }),
  }));
}

describe("checkConcurrentProposal", () => {
  beforeEach(() => {
    vi.resetModules();
  });

  it("returns hasConcurrent=false when no candidate rows are in the table", async () => {
    setupConcurrencyMocks([]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "Draft homepage hero",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(false);
  });

  it("excludes rows authored by the current user", async () => {
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_ME", // same user — skip
        args: JSON.stringify({ title: "Draft homepage hero" }),
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "Draft homepage hero",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(false);
  });

  it("returns hasConcurrent=true with metadata when another user has a fuzzy-matching pending proposal in same channel within window", async () => {
    const recent = new Date(Date.now() - 10_000); // 10s ago
    setupConcurrencyMocks([
      makeRow({
        id: "prop_other",
        userSlackId: "U_OTHER",
        channelId: "C_TEST_001",
        toolName: "create_week_item",
        args: JSON.stringify({ title: "Draft homepage hero" }),
        createdAt: recent,
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "Draft homepage hero", // exact match - dice = 1
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(true);
    if (result.hasConcurrent) {
      expect(result.otherUser).toBe("U_OTHER");
      expect(result.otherTitle).toBe("Draft homepage hero");
      expect(result.createdAt.getTime()).toBe(recent.getTime());
    }
  });

  it("excludes rows older than 60 seconds (window edge)", async () => {
    const stale = new Date(Date.now() - 61_000); // 61s ago - just outside
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_OTHER",
        args: JSON.stringify({ title: "Draft homepage hero" }),
        createdAt: stale,
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "Draft homepage hero",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(false);
  });

  it("excludes rows in a different channel", async () => {
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_OTHER",
        channelId: "C_DIFFERENT",
        args: JSON.stringify({ title: "Draft homepage hero" }),
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "Draft homepage hero",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(false);
  });

  it("excludes rows with a different toolName (task vs project)", async () => {
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_OTHER",
        toolName: "create_project",
        args: JSON.stringify({ name: "Draft homepage hero" }),
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "Draft homepage hero",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(false);
  });

  it("excludes rows whose title does not fuzzy-match (below threshold)", async () => {
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_OTHER",
        args: JSON.stringify({ title: "Completely unrelated kickoff" }),
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "Draft homepage hero",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(false);
  });

  it("uses `name` field from args for project toolName", async () => {
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_OTHER",
        toolName: "create_project",
        args: JSON.stringify({ name: "Website Build" }),
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_project",
      fuzzyTitle: "Website Build",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(true);
    if (result.hasConcurrent) {
      expect(result.otherTitle).toBe("Website Build");
    }
  });

  it("uses `fullName` field from args for team_member toolName", async () => {
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_OTHER",
        toolName: "create_team_member",
        args: JSON.stringify({ fullName: "Sam Rivera" }),
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_team_member",
      fuzzyTitle: "Sam Rivera",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(true);
    if (result.hasConcurrent) {
      expect(result.otherTitle).toBe("Sam Rivera");
    }
  });

  it("returns hasConcurrent=false when fuzzyTitle is empty (nothing to match against)", async () => {
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_OTHER",
        args: JSON.stringify({ title: "Some Task" }),
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(false);
  });

  it("handles candidate rows with empty / missing title field gracefully", async () => {
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_OTHER",
        args: JSON.stringify({}), // no title
      }),
      makeRow({
        userSlackId: "U_OTHER",
        args: "not valid json", // malformed
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "Draft homepage hero",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(false);
  });

  it("excludes already-cancelled / submitted rows (status != pending)", async () => {
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_OTHER",
        status: "cancelled",
        args: JSON.stringify({ title: "Draft homepage hero" }),
      }),
      makeRow({
        userSlackId: "U_OTHER",
        status: "submitted",
        args: JSON.stringify({ title: "Draft homepage hero" }),
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "Draft homepage hero",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(false);
  });

  it("matches case-insensitively (delegated to fuzzyMatchCandidates)", async () => {
    setupConcurrencyMocks([
      makeRow({
        userSlackId: "U_OTHER",
        args: JSON.stringify({ title: "draft HOMEPAGE hero" }),
      }),
    ]);
    const { checkConcurrentProposal } = await import("./concurrency-check");

    const result = await checkConcurrentProposal({
      toolName: "create_week_item",
      fuzzyTitle: "DRAFT homepage HERO",
      currentUserSlackId: "U_ME",
      currentChannelId: "C_TEST_001",
    });
    expect(result.hasConcurrent).toBe(true);
  });
});

/**
 * Concurrency soft-warn helper (Wave 11 / Builder 11).
 *
 * Fires at modal-open time. When a user opens a `create` modal we look up
 * other PENDING `bot_modal_proposals` in the SAME channel for the SAME
 * toolName authored by a DIFFERENT user within the LAST 60 SECONDS. If any
 * candidate's title fuzzy-matches the title we're about to render, we surface
 * a non-blocking soft-warn back to the caller, who renders it as a Block Kit
 * context block above the parent picker (or top of modal for non-parent
 * modals).
 *
 * This is intentionally a SOFT warn - the modal still opens. Users can dismiss
 * the soft-warn implicitly by submitting; the goal is to nudge two teammates
 * who happened to start the same form within ~1 minute of each other to talk
 * before saving duplicates.
 *
 * Design notes:
 *   - We pull a small candidate set with the cheap filters (status / channel /
 *     toolName / time-window / not-self) at the SQL boundary, then run the
 *     fuzzy-match in JS so we can reuse the shared Sørensen-Dice utility.
 *     Cardinality is bounded by the 60s window; this is fine for production
 *     load.
 *   - Title extraction is toolName-discriminated: tasks store `title`,
 *     projects store `name`, team-members store `fullName`. JSON parse errors
 *     and missing fields short-circuit to "no match" so a malformed args row
 *     can't crash the open path.
 *   - Empty `fuzzyTitle` returns `hasConcurrent: false` immediately - there's
 *     no meaningful match to compute and surfacing a warn pinned to a blank
 *     title would be noise.
 */

import { and, eq, gt, ne } from "drizzle-orm";
import { getRunwayDb } from "@/lib/db/runway";
import { botModalProposals } from "@/lib/db/runway-schema";
import { fuzzyMatchCandidates } from "@/lib/runway/fuzzy-match";

const CONCURRENCY_WINDOW_MS = 60 * 1000;

/**
 * Inputs for the concurrency check. `toolName` mirrors the staged proposal's
 * `toolName` column (e.g. `create_week_item`). `fuzzyTitle` is the title /
 * name / fullName extracted from THIS user's args - the value we want to
 * compare against pending peers.
 */
export interface CheckConcurrentProposalParams {
  toolName: string;
  fuzzyTitle: string;
  currentUserSlackId: string;
  currentChannelId: string;
}

export type ConcurrentProposalResult =
  | { hasConcurrent: false }
  | {
      hasConcurrent: true;
      otherUser: string;
      otherTitle: string;
      createdAt: Date;
    };

/** Candidate row shape — tightly scoped to the columns this helper reads. */
interface ConcurrencyCandidate {
  id: string;
  userSlackId: string;
  args: string;
  createdAt: Date;
}

/**
 * Pull pending peers from the DB, filter by fuzzy match, return the first
 * match (or `{hasConcurrent: false}`).
 */
export async function checkConcurrentProposal(
  params: CheckConcurrentProposalParams,
): Promise<ConcurrentProposalResult> {
  const { toolName, fuzzyTitle, currentUserSlackId, currentChannelId } = params;

  // No title to match against -> nothing to warn about.
  if (typeof fuzzyTitle !== "string" || fuzzyTitle.trim().length === 0) {
    return { hasConcurrent: false };
  }

  const cutoff = new Date(Date.now() - CONCURRENCY_WINDOW_MS);

  // SQL-side filters keep candidate cardinality minimal. The createdAt > cutoff
  // filter alone is a fast index scan via the (user_slack_id, created_at)
  // covering index when the row counts grow.
  const candidates = (await getRunwayDb()
    .select()
    .from(botModalProposals)
    .where(
      and(
        eq(botModalProposals.status, "pending"),
        eq(botModalProposals.toolName, toolName),
        eq(botModalProposals.channelId, currentChannelId),
        ne(botModalProposals.userSlackId, currentUserSlackId),
        gt(botModalProposals.createdAt, cutoff),
      ),
    )) as ConcurrencyCandidate[];

  if (candidates.length === 0) {
    return { hasConcurrent: false };
  }

  // Defensive in-JS re-filter: the DB stub used in tests returns rows verbatim
  // without applying the SQL filter; production drizzle obeys the .where()
  // clause. Re-applying here makes the helper hermetic against either driver
  // path and keeps the contract obvious to readers.
  const filtered = candidates.filter((row) => {
    if (row.userSlackId === currentUserSlackId) return false;
    if (row.createdAt instanceof Date) {
      if (row.createdAt.getTime() <= cutoff.getTime()) return false;
    }
    return true;
  });

  if (filtered.length === 0) {
    return { hasConcurrent: false };
  }

  // Fuzzy match against the toolName-appropriate title field.
  const matches = fuzzyMatchCandidates(
    fuzzyTitle,
    filtered,
    (c) => extractTitle(toolName, c.args),
  );

  if (matches.length === 0) {
    return { hasConcurrent: false };
  }

  const winner = matches[0];
  return {
    hasConcurrent: true,
    otherUser: winner.userSlackId,
    otherTitle: extractTitle(toolName, winner.args),
    createdAt: winner.createdAt,
  };
}

/**
 * Pull the title-equivalent field out of a candidate's args JSON. The field
 * name is toolName-discriminated:
 *   - create_week_item / update_week_item -> `title`
 *   - create_project / update_project     -> `name`
 *   - create_team_member / update_team_member -> `fullName`
 *
 * Returns "" on any failure so fuzzyMatchCandidates filters the row out
 * cleanly (sorensenDice("X", "") -> 0, below threshold).
 */
function extractTitle(toolName: string, argsRaw: string): string {
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(argsRaw) as Record<string, unknown>;
  } catch {
    return "";
  }
  if (toolName === "create_project" || toolName === "update_project") {
    return typeof parsed.name === "string" ? parsed.name : "";
  }
  if (toolName === "create_team_member" || toolName === "update_team_member") {
    return typeof parsed.fullName === "string" ? parsed.fullName : "";
  }
  return typeof parsed.title === "string" ? parsed.title : "";
}

